 draw();a.addEventListener('click',e=>{const b=e.target.closest('[data-cell]'),d=e.target.closest('[data-dir]');if(b)move(b.dataset.cell.split(',').map(Number));else if(d){const v=d.dataset.dir.split(',').map(Number);move([position[0]+v[0],position[1]+v[1]]);}});const keys=e=>{const dirs={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(dirs[e.key]){e.preventDefault();move([position[0]+dirs[e.key][0],position[1]+dirs[e.key][1]]);}};document.addEventListener('keydown',keys);G.cleanup.push(()=>document.removeEventListener('keydown',keys));
