const caseTools={data:['Стоп','Проверь источник','Проверь источник','Не сообщай код'],social:['Стоп','Проверь источник','Настрой приватность','Попроси помощи'],links:['Стоп','Проверь источник','Проверь источник','Стоп'],pressure:['Стоп','Сделай скриншот','Заблокируй','Попроси помощи'],conflict:['Стоп','Сделай скриншот','Заблокируй','Попроси помощи'],truth:['Стоп','Проверь источник','Проверь источник','Проверь источник'],games:['Не сообщай код','Проверь источник','Стоп','Стоп'],money:['Стоп','Проверь источник','Проверь источник','Стоп'],free:['Стоп','Проверь источник','Не сообщай код','Попроси помощи'],help:['Стоп','Сделай скриншот','Проверь источник','Попроси помощи']};
