function caseConfiguration(id,age=state.age){
 const r=Object.keys(D.ageNames).indexOf(age);
 let tools=[...caseTools[id]],prompts=[...casePrompts[id]],plan=[...DN_CONTENT.plans[id]];
 if(r===0){tools=[id==='games'?'Не сообщай код':'Стоп','Попроси помощи'];prompts=['На экране просьба или предложение. Как начнёшь?','Ты не уверен, что делать дальше. Кто может помочь?'];}
 else if(r===1){tools=id==='data'||id==='pressure'?['Не сообщай код','Стоп','Попроси помощи']:['Стоп','Проверь источник','Попроси помощи'];prompts=['От тебя ждут действия или личных сведений. Как сохранить контроль?','Что поможет приостановить или проверить просьбу?','Если просьба всё ещё вызывает сомнение, какой ресурс доступен?'];}
 else if(id==='games'&&r===4){tools=['Стоп','Проверь источник','Стоп','Попроси помощи'];prompts=['Программа требует установки и изменения защиты. Твоё первое действие?','Где можно проверить происхождение программы и правила игры?','Как поступить с защитой, пока источник не подтверждён?','Если самостоятельно оценить риск не получилось, какой ресурс доступен?'];}
 else if(id==='data'&&r===3){tools=['Стоп','Проверь источник','Проверь источник','Настрой приватность'];prompts=['Форма просит личные сведения. Как начнёшь?','Что поможет установить организатора и назначение сбора?','Как сопоставить адрес ресурса с известным организатором?','Что делать с избыточными личными сведениями до подтверждения?'];}
 if(r<2||id==='games'&&r===4||id==='data'&&r===3){const labels={'Стоп':'Приостановить действие до проверки','Проверь источник':'Проверить через надёжный независимый канал','Не сообщай код':'Сохранить пароль и код у себя','Настрой приватность':'Сохранить контроль личных сведений','Попроси помощи':'Показать ситуацию подходящему взрослому'};plan=tools.map(t=>labels[t]);}
 return {tools,prompts,plan};
}
function toolConsequence(name){return({'Стоп':'Действие приостановлено. Данные, деньги и файлы пока не переданы. Есть время для проверки.','Проверь источник':'Выбран независимый канал проверки. Сопоставь известный адрес, автора и условия; слова отправителя сами по себе не являются подтверждением.','Не сообщай код':'Пароль и код не переданы. Контроль доступа остался у тебя.','Сделай скриншот':'Сохранены содержание, отправитель и время — для проверки с тем, кто поможет.','Заблокируй':'Нежелательный контакт ограничен средствами учебного сервиса. Можно дополнительно использовать жалобу.','Настрой приватность':'Личные сведения не публикуются автоматически и не передаются непроверенному контакту.','Попроси помощи':'Ситуация показана подходящему доверенному человеку. Для младших это следующий шаг при сомнении; для старших — ресурс при неопределённости.'})[name];}
types.case=(a,s)=>{
 const c=window.IAR_CASES[G.w.number-1].ages[state.age],progress=G.data.progress||0;let at=progress;const {plan,prompts,tools}=caseConfiguration(G.w.id);let reflection=G.data.reflection||'';
 function draw(){const complete=at>=plan.length;
 a.innerHTML=instruction('Выбери инструмент рюкзака и перенеси его к ситуации. При необходимости нажми карточку, затем на область действия.')+`<div class="case-simulator"><div class="case-phone"><div class="messenger-top">${icon(G.w.icon)}<b>Твоя ситуация</b><span>${Math.min(at+1,tools.length)}/${tools.length}</span></div><div class="case-messages"><div class="bubble npc">${escape(c.situation)}</div>${plan.slice(0,at).map((p,i)=>`<div class="bubble self">${escape(p)}</div><div class="bubble system">${escape(toolConsequence(tools[i]))}</div>`).join('')}</div>${!complete?`<div class="case-target" data-drop="action" tabindex="0" role="button"><small>ЗАДАЧА СЕЙЧАС</small><b>${escape(prompts[at])}</b><span>Примени подходящий инструмент</span></div>`:''}</div><aside class="case-tools"><h3>${icon('bag')} Твой рюкзак</h3><div class="case-tool-bank">${state.inventory.map(name=>`<button class="drag-card tool-card" data-drag="${escape(name)}">${icon(DN_CONTENT.tools[name]?.icon)}${escape(name)}</button>`).join('')}</div>${!complete?'<button class="secondary unsafe-case" id="unsafe-case">Выполнить исходную просьбу сразу</button>':''}<span class="case-use-note">Применено действий: ${at} / ${tools.length}</span></aside></div>${complete?`<div class="reflection-panel"><h3>Что изменилось после твоих действий?</h3><p>${escape(c.safe)}</p>${D.rank()>=2?`<label>Объясни своё решение для обсуждения с педагогом<textarea id="reflection" maxlength="600" rows="3" placeholder="Какие признаки и последствия ты учёл?">${escape(reflection)}</textarea></label><p class="small-note">Объяснение сохраняется для обсуждения. Тренажёр не оценивает свободный текст автоматически.</p>`:''}${checkButton('Завершить ситуацию')}</div>`:''}`;
 if(!complete){$('#unsafe-case').onclick=()=>{G.error(unsafeConsequence(G.w.id)+' Можно остановиться и изменить действие.');$('.case-messages').insertAdjacentHTML('beforeend',`<div class="bubble system warning">${escape(unsafeConsequence(G.w.id))}</div>`);};}
 else{if($('#reflection'))$('#reflection').oninput=e=>{reflection=e.target.value;G.data.reflection=reflection;G.store();};$('#check-task').onclick=()=>{if(D.rank()>=2&&reflection.trim().length<8){D.toast('Добавь короткое объяснение: какой признак ты заметил и почему это действие снижает риск.');$('#reflection').focus();return;}state.results[G.k]=state.results[G.k]||undefined;G.done((D.young()?'Ты остановился и привлёк поддержку в новой ситуации. ':'Ты перенёс способ действия в новую ситуацию: остановился, проверил и выбрал безопасное действие. ')+c.safe);if(state.results[G.k]){state.results[G.k].reflection=reflection;D.save();}};}
 }
 draw();drag(a,(name,zone)=>{if(zone!=='action'||at>=tools.length)return;if(name===tools[at]){state.uses[name]=(state.uses[name]||0)+1;G.action('case'+at,toolConsequence(name));at++;G.data.progress=at;G.store();draw();}else G.error(`Инструмент «${name}» полезен в другой задаче. Сейчас подумай: ${prompts[at]}`);});
};
function unsafeConsequence(id){return({data:'Передача кода или пароля может дать другому человеку доступ к аккаунту.',social:'Личные сведения и секретная встреча увеличивают риск, пока собеседник не проверен.',links:'Ссылка и вложение могут вести к краже доступа. Имя адресата не подтверждает письмо.',pressure:'Выполнение требования не гарантирует прекращение давления.',conflict:'Пересылка или ответная травля увеличивают вред и аудиторию унижения.',truth:'Пересылка до проверки распространяет сведения, подлинность которых неизвестна.',games:'Передача аккаунта или отключение защиты может лишить доступа и повредить устройству.',money:'Чужая просьба о переводе может привести к потере денег или вовлечению в непонятную схему.',free:'После бонуса могут потребовать личные данные, деньги и повторные платежи.',help:'Поспешное действие при неопределённости может увеличить риск.'})[id];}
function caseConsequence(id,i){const phrases={
 data:['Ввод приостановлен. Данные ещё не переданы.','Известное приложение открыто независимо от сообщения.','Запрос сверяется с уведомлениями и настройками аккаунта.','Пароль и код не переданы человеку. Контроль аккаунта сохранён.'],
 social:['Личные требования не выполняются автоматически.','Сведения сопоставляются с независимым источником; фотография не считается доказательством.','Личные сведения остаются под твоим контролем.','Контакт обсуждается с доверенным человеком. При риске можно прекратить общение.'],
 links:['Переход и загрузка приостановлены.','Сервис открыт по известному адресу.','Просьба проверяется другим каналом; данные из письма сами по себе ничего не доказывают.','Неизвестное вложение не запущено.'],
 pressure:['Неприятное требование не выполнено.','Важные сообщения, отправитель и время сохранены.','Нежелательный контакт ограничен средствами сервиса.','Ты получил ресурс поддержки, не вступая в ответную угрозу.'],
 conflict:['Ты не добавляешь аудиторию травле.','Факты сохранены для обращения, без публичной пересылки.','Жалоба и ограничения применяются по ситуации.','Педагог или доверенный взрослый может подключиться к снижению вреда.'],
 truth:['Непроверенная публикация не распространяется.','Найдено происхождение сведений; отсутствие автора отмечено как неопределённость.','Дата, полная версия и подпись сравниваются.','Копии одного сообщения отделены от независимых сведений. Вывод делается после проверки.'],
 games:['Доступ к аккаунту остался у тебя.','Предложение сопоставлено с официальными правилами и каналом игры.','Защита устройства не отключена ради обещания преимущества.','Сомнительное действие отклонено.'],
 money:['Деньги ещё не отправлены.','Просьба сверяется с ранее известным каналом связи.','Условия, организация и получатель проверяются до любой операции.','Непонятная операция не выполняется; при сомнении можно обратиться за консультацией.'],
 free:['Участие и регистрация не начаты.','Обещания сопоставлены с реальными условиями, а не с рекламным слоганом.','Персональные и платёжные данные не переданы, деньги не отправлены.','Сомнительное предложение можно обсудить; для старших учитывается ограничение 18+.'],
 help:['Ты получил время для анализа, не действуя наугад.','Неизвестное и доступные факты зафиксированы.','Надёжные сведения отделены от предположений.','Если существенная неопределённость остаётся, поддержка помогает снизить риск.']
};return phrases[id][i];}
function final(a){
 let at=state.final[state.age]?.at||0;let mistakes=state.final[state.age]?.mistakes||0;const order=DN_CONTENT.worlds;
 function persist(){state.final[state.age]={...state.final[state.age],at,mistakes};D.save();}
 function draw(){if(at>=10){a.innerHTML=`<div class="route-finish">${icon('trophy')}<h2>Безопасный день завершён!</h2><p>Все десять тем встретились в одном маршруте. Ты применял проверку и поддержку в изменяющихся ситуациях.</p><div class="stats-strip"><span><b>${state.xp}</b> XP</span><span><b>${D.stars()}</b> звёзд</span><span><b>${mistakes}</b> исправлений</span></div><button class="primary" id="final-map">На карту</button><button class="secondary" id="final-repeat">Пройти день снова</button></div>`;$('#final-map').onclick=D.app.map;$('#final-repeat').onclick=()=>{at=0;mistakes=0;persist();draw();};return;}
 const w=order[at],c=IAR_CASES[w.number-1].ages[state.age];a.innerHTML=`<div class="day-progress"><div class="meter"><i style="width:${at*10}%"></i></div><span>Событие ${at+1}/10 · ${escape(w.title)}</span></div><div class="final-scene"><span class="eyebrow">${String(9+at).padStart(2,'0')}:15 · СОБЫТИЕ ДНЯ</span><h2>${escape(c.situation)}</h2><p>Выбери инструмент для первого действия. Затем прочитай его последствие и объясни, что проверишь дальше.</p><div class="final-tools">${shuffled(state.inventory).map(name=>`<button class="secondary" data-day-tool="${escape(name)}">${icon(DN_CONTENT.tools[name]?.icon)}${escape(name)}</button>`).join('')}</div><div id="day-feedback" role="status"></div></div>`;
 $$('[data-day-tool]').forEach(b=>b.onclick=()=>{const name=b.dataset.dayTool,expected=caseConfiguration(w.id).tools[0];if(name===expected||(name==='Попроси помощи'&&D.young())){state.uses[name]=(state.uses[name]||0)+1;persist();$('#day-feedback').innerHTML=`<div class="feedback good"><p>${escape(toolConsequence(name))}</p></div><label>Следующая проверка или действие<textarea id="day-reflection" rows="2" maxlength="400" placeholder="Что проверишь и к кому обратишься при сомнении?"></textarea></label><button class="primary" id="next-day">Продолжить день</button>`;$('#next-day').onclick=()=>{const text=$('#day-reflection').value.trim();if(!D.young()&&text.length<8){D.toast('Запиши следующее действие для обсуждения.');return;}const previous=state.final[state.age]?.reflections||[];previous[at]=text;at++;const won=at===10;if(won&&!state.final[state.age]?.rewarded){state.xp+=200;}const awarded=state.final[state.age]?.rewarded||won;state.final[state.age]={at,mistakes,reflections:previous,rewarded:awarded};D.save();D.app.refreshHeader();D.effect(won?'reward':'success');draw();};}else{mistakes++;persist();$('#day-feedback').innerHTML=`<div class="feedback bad"><p>Этот инструмент может пригодиться позже. Сначала нужно приостановить рискованное действие или сохранить контроль аккаунта. Попробуй изменить выбор.</p></div>`;D.effect('error');}});
 }
 draw();return ()=>{};
}
window.DN.games={mount,final,types,caseTools,caseConfiguration};
